def solve(grid):
    # Locate the separator row consisting entirely of 4s
    sep_index = None
    for i, row in enumerate(grid):
        if row and all(cell == 4 for cell in row):
            sep_index = i
            break

    if sep_index is None:
        # No separator – treat the whole grid as the bottom part
        top = []
        bottom = grid
    else:
        top = grid[:sep_index]
        bottom = grid[sep_index + 1:]

    rows = len(bottom)
    cols = len(bottom[0]) if rows else 0
    result = [[0] * cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            # If the values are the same (both 0 or both 2) → 0,
            # otherwise (one is 0, the other 2) → 3
            result[r][c] = 0 if top[r][c] == bottom[r][c] else 3

    return result

